"""Feast feature definitions: the version-controlled "feature contract".Two FeatureViews (athlete_features_v1 / _v2) = the two feature versions.Two FeatureServices bundle them as the contract a model consumes.Versioning here is by name + git: a new feature set = a new FeatureView, never an editto one a trained model already depends on."""import sysfrom datetime import timedeltafrom pathlib import Pathfrom feast import Entity, FeatureService, FeatureView, Field, FileSourcefrom feast.types import Float32, Int64, Stringsys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))from config import ENTITY, FEATURE_VERSIONS, FEATURES_DIR, TS  # noqa: E402athlete = Entity(name="athlete", join_keys=[ENTITY], description="One CrossFit athlete")# The feature tables live in the project's data/features/ folder (see src/config.py),# not inside feature_repo/. This folder holds only Feast's settings and definitions.def make_view(version: str) -> FeatureView:    spec = FEATURE_VERSIONS[version]    schema = [Field(name=n, dtype=Int64 if n.startswith(("is_", "bg_", "exp_", "sched_", "eat_")) else Float32)              for n in spec["numeric"]]    schema += [Field(name=n, dtype=String) for n in spec["categorical"]]    return FeatureView(        name=f"athlete_features_{version}",        entities=[athlete],        ttl=timedelta(days=3650),            # how far back a feature value is still valid        schema=schema,        source=FileSource(path=str(FEATURES_DIR / f"athlete_features_{version}.parquet"), timestamp_field=TS),    )# Feast only registers module-level objects, so each version is a named variable.athlete_features_v1 = make_view("v1")athlete_features_v2 = make_view("v2")athlete_model_v1 = FeatureService(name="athlete_model_v1", features=[athlete_features_v1])athlete_model_v2 = FeatureService(name="athlete_model_v2", features=[athlete_features_v2])